import RNA, random, multiprocessing
tgt='(((((((((((((((.(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).(((.....))).(((((.((.....)).((.....)).((.....)).((.....)).((.....)).))))).)))))))))))))))'
n=len(tgt)
def cost(seq):
    fc=RNA.fold_compound(seq)
    mfe=fc.mfe()[0]
    return RNA.bp_distance(mfe,tgt), mfe
def init_seq():
    seq=['A']*n
    stack=[]; pairs=[]
    for i,c in enumerate(tgt):
        if c=='(': stack.append(i)
        elif c==')': pairs.append((stack.pop(),i))
    for j,i in pairs: seq[j]='G'; seq[i]='C'
    i=0
    while i<n:
        if tgt[i]=='.':
            j=i
            while j<n and tgt[j]=='.': j+=1
            if j-i==5: cap='GAAAC'
            elif j-i==3: cap='GAA'
            else: cap='A'*(j-i)
            for k,ch in enumerate(cap): seq[i+k]=ch
            i=j
        else: i+=1
    return seq
def search(seed):
    random.seed(seed)
    best=init_seq()
    # add random jitter
    for i in range(n):
        if best[i]=='A' and random.random()<0.3: best[i]=random.choice('ACGU')
    cur=''.join(best); c,mfe=cost(cur)
    for it in range(1500):
        if c==0: return (0,''.join(best))
        mm=[i for i in range(n) if mfe[i]!=tgt[i]]
        if not mm: return (0,''.join(best))
        bestc=best[:]; bestc_c=c
        for _ in range(30):
            i=random.choice(mm)
            old=best[i]
            best[i]=random.choice('ACGU')
            nc,nmfe=cost(''.join(best))
            if nc<c:
                c=nc; mfe=nmfe; bestc=best[:]; bestc_c=c
            elif nc==c:
                pass  # accept lateral
            else:
                best[i]=old
        if c==0: return (0,''.join(best))
    return (c,''.join(best))
if __name__=='__main__':
    with multiprocessing.Pool(32) as p:
        results=p.map(search, range(64))
    results.sort()
    print('best',results[0][0])
    print(results[0][1])
    fc=RNA.fold_compound(results[0][1])
